using System.Text.RegularExpressions;
namespace LSE.AutoCADElectrical.Librarian;
// LSE part number = [Category][Mfr code][Type][Sequence] (2+3+2+7 = 14 characters by default; the widths come from the workbook).
// The sequence is counted per Category + Mfr + Type across every family table of default_cat.mdb (the authority for
// issued numbers) and across the numbers already listed on the workbook tab, so a number is never issued twice.
public static class PartNumberService {
 public static void Validate(NamingFormat f,PartNumberRequest r){
  if(!Regex.IsMatch(r.Category,$"^[0-9]{{{f.CategoryChars}}}$"))throw new InvalidOperationException($"Category code must be {f.CategoryChars} digits (for example 45).");
  if(!Regex.IsMatch(r.ManufacturerCode,$"^[A-Za-z]{{{f.ManufacturerChars}}}$"))throw new InvalidOperationException($"Manufacturer code must be {f.ManufacturerChars} letters (for example BUS).");
  if(!Regex.IsMatch(r.Type,$"^[A-Za-z]{{{f.TypeChars}}}$"))throw new InvalidOperationException($"Type code must be {f.TypeChars} letters (for example FH).");
  if(r.IsManual){string pn=Normalize(r.ManualPartNumber);if(!StandardForm(f).IsMatch(pn))throw new InvalidOperationException($"The part number must be {f.Length} characters: {f.CategoryChars} digits, {f.ManufacturerChars} letters, {f.TypeChars} letters, {f.SequenceChars} digits (for example 45BUSFH0000001).");if(!pn.StartsWith(r.Prefix,StringComparison.Ordinal))throw new InvalidOperationException($"The part number {pn} does not start with the chosen category, manufacturer and type codes ({r.Prefix}).");}}
 public static Regex Pattern(NamingFormat f,string prefix)=>new("^"+Regex.Escape(prefix.ToUpperInvariant())+$"([0-9]{{{f.SequenceChars}}})$");
 public static Regex StandardForm(NamingFormat f)=>new($"^[0-9]{{{f.CategoryChars}}}[A-Z]{{{f.ManufacturerChars}}}[A-Z]{{{f.TypeChars}}}[0-9]{{{f.SequenceChars}}}$");
 public static string Normalize(string v)=>v.Trim().ToUpperInvariant();
 // Legacy ERP numbers kept under rule 7 (45BUSCF1633301, 45FSCFH3238731, ...) fit the 14-character form but carry a
 // 7-significant-digit tail; numbers issued under the standard are zero-padded (0000001, 0000002, ...). A sequence at or
 // above LegacyFloor (1,000,000 for 7 digits) is therefore treated as legacy: it stays reserved, but it does not move the
 // counter, so the next number after 0000011 is 0000012 and not 1691251.
 public static long LegacyFloor(NamingFormat f)=>(long)Math.Pow(10,f.SequenceChars-1);
 public static bool IsLegacySequence(NamingFormat f,long sequence)=>sequence>=LegacyFloor(f);
 public static long Highest(NamingFormat f,string prefix,IEnumerable<string> existing){var p=Pattern(f,prefix);long h=0;foreach(string v in existing){var m=p.Match(Normalize(v));if(m.Success&&long.TryParse(m.Groups[1].Value,out long n)&&!IsLegacySequence(f,n)&&n>h)h=n;}return h;}
 public static string Format(NamingFormat f,string prefix,long sequence){long cap=(long)Math.Pow(10,f.SequenceChars)-1;if(sequence<1||sequence>cap)throw new InvalidOperationException($"Sequence exhausted for {prefix}: every number up to {cap} is used.");return prefix.ToUpperInvariant()+sequence.ToString().PadLeft(f.SequenceChars,'0');}
 // catalogValues: (part number, family table) pairs read from default_cat.mdb; workbookValues: numbers listed on the workbook tabs.
 public static PartNumberPreview Preview(NamingFormat f,PartNumberRequest r,IReadOnlyCollection<(string Value,string Table)> catalogValues,IReadOnlyCollection<string> workbookValues){
  Validate(f,r);string prefix=r.Prefix;var p=Pattern(f,prefix);var x=new PartNumberPreview{Prefix=prefix};var used=new HashSet<long>();
  foreach(var (v,t) in catalogValues){var m=p.Match(Normalize(v));if(!m.Success)continue;x.CatalogMatches++;long n=long.Parse(m.Groups[1].Value);used.Add(n);if(IsLegacySequence(f,n)){x.CatalogLegacy++;continue;}if(n>x.HighestInCatalog){x.HighestInCatalog=n;x.HighestInCatalogTable=t;}}
  foreach(string v in workbookValues){var m=p.Match(Normalize(v));if(!m.Success)continue;x.WorkbookMatches++;long n=long.Parse(m.Groups[1].Value);used.Add(n);if(IsLegacySequence(f,n)){x.WorkbookLegacy++;continue;}if(n>x.HighestInWorkbook)x.HighestInWorkbook=n;}
  string Legacy(int k)=>k==0?"":$" ({k} legacy ERP number(s) with 7 significant digits kept under rule 7, not counted)";
  var lines=new List<string>{x.CatalogMatches==0?$"No {prefix} number is issued in default_cat.mdb yet.":x.HighestInCatalog==0?$"default_cat.mdb: {x.CatalogMatches} {prefix} number(s), none issued under the standard yet{Legacy(x.CatalogLegacy)}.":$"default_cat.mdb: {x.CatalogMatches} {prefix} number(s), highest issued {Format(f,prefix,x.HighestInCatalog)} in table {x.HighestInCatalogTable}{Legacy(x.CatalogLegacy)}.",x.WorkbookMatches==0?$"The workbook lists no {prefix} number.":x.HighestInWorkbook==0?$"Workbook: {x.WorkbookMatches} {prefix} number(s), none issued under the standard yet{Legacy(x.WorkbookLegacy)}.":$"Workbook: {x.WorkbookMatches} {prefix} number(s), highest issued {Format(f,prefix,x.HighestInWorkbook)}{Legacy(x.WorkbookLegacy)}."};
  if(r.IsManual){string pn=Normalize(r.ManualPartNumber);if(catalogValues.Any(c=>Normalize(c.Value).Equals(pn,StringComparison.Ordinal)))throw new InvalidOperationException($"Part number {pn} is already issued in default_cat.mdb (table {catalogValues.First(c=>Normalize(c.Value).Equals(pn,StringComparison.Ordinal)).Table}).");x.PartNumber=pn;lines.Add(workbookValues.Any(w=>Normalize(w).Equals(pn,StringComparison.Ordinal))?$"{pn} is typed by hand; it is listed on the workbook tab (an existing LSE number kept, rule 7) and not yet in the catalog.":$"{pn} is typed by hand and is unused in both the catalog and the workbook.");}
  else{long next=Math.Max(x.HighestInCatalog,x.HighestInWorkbook)+1;int skipped=0;while(used.Contains(next)){next++;skipped++;}x.PartNumber=Format(f,prefix,next);lines.Add($"Next unused sequence: {x.PartNumber}"+(x.HighestInWorkbook>x.HighestInCatalog?" (the workbook already reserved numbers above the catalog's highest, so the count continues after them)":"")+(skipped>0?$" ({skipped} number(s) skipped because they are already used)":"")+".");}
  x.Explanation=string.Join(Environment.NewLine,lines);return x;}
 public static string Next(NamingFormat f,string prefix,IReadOnlyCollection<string> existing){var p=Pattern(f,prefix);var used=new HashSet<long>();foreach(string v in existing){var m=p.Match(Normalize(v));if(m.Success)used.Add(long.Parse(m.Groups[1].Value));}long n=Highest(f,prefix,existing)+1;while(used.Contains(n))n++;return Format(f,prefix,n);}
 public static (string Category,string Manufacturer,string Type,long Sequence)? Split(NamingFormat f,string partNumber){string pn=Normalize(partNumber);if(!StandardForm(f).IsMatch(pn))return null;return(pn[..f.CategoryChars],pn.Substring(f.CategoryChars,f.ManufacturerChars),pn.Substring(f.CategoryChars+f.ManufacturerChars,f.TypeChars),long.Parse(pn[^f.SequenceChars..]));}
 public static string PurchaseDescription(string description,string catalogNumber)=>description.Trim().Length==0?"":catalogNumber.Trim().Length==0?description.Trim():description.Trim()+", MPN "+catalogNumber.Trim();
 public static List<string> DescriptionProblems(NamingTab? tab,string description){var x=new List<string>();string d=description.Trim();if(d.Length==0){x.Add("Description is required.");return x;}if(d.Length>150)x.Add($"Description is {d.Length} characters; the catalog column holds 150.");else if(d.Length>100)x.Add($"Description is {d.Length} characters; the LSE standard asks for 100 or fewer.");if(d.Any(c=>char.IsLetter(c)&&char.IsLower(c)))x.Add("Description must be ALL CAPS.");if(d.Contains("N/A",StringComparison.OrdinalIgnoreCase))x.Add("Leave out fields that do not apply; never write N/A.");if(d.IndexOfAny(new[]{'°','Ø','″','′'})>=0)x.Add("Description must not contain degree, diameter or prime symbols.");return x;}
}
